(7680281, 1256393, 4008, '<td valign="top">Lovely warm colors, nice balance.</td>', 'Lovely warm colors, nice balance.', '2020-11-27 04:05:34.000000', NULL, 1),
(7680283, 1256619, 4008, '<td valign="top">Nice still life. The bird is a nice reference. Unfortunately there are post processing artefacts along the edges of the berries and branches.</td>', 'Nice still life. The bird is a nice reference. Unfortunately there are post processing artefacts along the edges of the berries and branches.', '2020-11-27 04:09:40.000000', NULL, 1),
(7680284, 1256646, 4008, '<td valign="top">Nice warm colors. Good elements for a still life. In my view the composition could be improved. There is too much foreground which is also in focus and lighter than the rest of the scene and therefore draws too much attention.</td>', 'Nice warm colors. Good elements for a still life. In my view the composition could be improved. There is too much foreground which is also in focus and lighter than the rest of the scene and therefore draws too much attention.', '2020-11-27 04:12:52.000000', NULL, 1),
(7680293, 1256536, 4008, '<td valign="top">Not sharp anywhere, a lot of motion blur.</td>', 'Not sharp anywhere, a lot of motion blur.', '2020-11-27 10:31:40.000000', NULL, 1),
(7680294, 1256650, 4008, '<td valign="top">Beautiful colors and nice soft finish.</td>', 'Beautiful colors and nice soft finish.', '2020-11-27 10:33:32.000000', NULL, 1),
(7680296, 1256425, 4008, '<td valign="top">Too much color fading.</td>', 'Too much color fading.', '2020-11-27 10:38:35.000000', NULL, 1),
