(7680300, 1256622, 4008, '<td valign="top">Beautiful still life with nice texture and nice gold colors all over. I am missing some of the soft finish. In my top 5.</td>', 'Beautiful still life with nice texture and nice gold colors all over. I am missing some of the soft finish. In my top 5.', '2020-11-27 10:42:21.000000', NULL, 1),
(7680304, 1256523, 4008, '<td valign="top">Very tasty image. Lovely use of soft focus. The background is a bit light and busy and draws too much attention in my view.</td>', 'Very tasty image. Lovely use of soft focus. The background is a bit light and busy and draws too much attention in my view.', '2020-11-27 10:56:08.000000', NULL, 1),
